"""Nur Dokument-/Referenz-/Rohbytepruefung; keine Produktausfuehrung."""
import hashlib
import json
import os
from pathlib import Path
import sys

ROOT = Path("F:/ChnobelRuntime/specification/v2-field-supplement-03/digest-targets")
SOURCES = ROOT / "sources.json"
EXCLUDED = ("v2-field-supplement-01", "adr0004", "0004-")

def sha(data):
    return hashlib.sha256(data).hexdigest()

def load():
    if SOURCES.exists():
        return json.loads(SOURCES.read_bytes())
    return {"purpose": "Rohbytebindung dieses engen Quellenauftrags, keine fachliche Freigabe", "immutableSources": [], "mutableContext": [], "excluded": ["Alte Teilabgabe v2-field-supplement-01", "ADR-0004-Entwurf und Stimmen", "Produkt-/Schema-/Validator-/Evaluator-/Testausfuehrung"], "implementationAuthorized": False, "blockerClosed": False}

def save(doc):
    SOURCES.write_bytes((json.dumps(doc, ensure_ascii=False, indent=2) + "\n").encode("utf-8"))

def check_path(raw):
    p = Path(raw)
    s = p.as_posix()
    if any(x.lower() in s.lower() for x in EXCLUDED):
        raise ValueError("Ausgeschlossene Quelle")
    if not s.startswith(("F:/ChnobelRuntime/", "F:/Projects/Chnobel/")):
        raise ValueError("Quelle ausserhalb des zugewiesenen Bereichs")
    return p

def add(kind, raw, expected=None):
    doc = load()
    p = check_path(raw)
    data = p.read_bytes()
    digest = sha(data)
    if expected is not None and digest != expected:
        raise ValueError(f"Eingabedigest weicht ab: {p}")
    key = "mutableContext" if kind == "context" else "immutableSources"
    for item in doc[key]:
        if item["path"] == p.as_posix():
            if item["sha256Before"] != digest and key == "immutableSources":
                raise ValueError(f"Normquelle seit Erfassung geaendert: {p}")
            return item
    item = {"path": p.as_posix(), "sha256Before": digest, "bytesBefore": len(data), "expectedSha256": expected, "sha256After": None, "bytesAfter": None, "unchanged": None}
    doc[key].append(item)
    save(doc)
    return item

def finish():
    doc = load()
    for key in ("immutableSources", "mutableContext"):
        for item in doc[key]:
            data = Path(item["path"]).read_bytes()
            item.update(sha256After=sha(data), bytesAfter=len(data), unchanged=sha(data) == item["sha256Before"])
    doc["immutableUnchanged"] = all(x["unchanged"] for x in doc["immutableSources"])
    doc["contextChangedPaths"] = [x["path"] for x in doc["mutableContext"] if not x["unchanged"]]
    doc["verificationBoundary"] = "Nur gelistete Eingabedateien; keine Aussage ueber den gesamten Repository- oder Manifestbaum. Elternarchive/Queue weder gelesen noch Normautoritaet. Kontext getrennt."
    save(doc)
    print(json.dumps({"immutableCount": len(doc["immutableSources"]), "immutableUnchanged": doc["immutableUnchanged"], "contextCount": len(doc["mutableContext"]), "contextChangedPaths": doc["contextChangedPaths"]}, ensure_ascii=False))
    if not doc["immutableUnchanged"]:
        raise SystemExit("Unveraenderliche Quelle abgewichen")

if __name__ == "__main__":
    if sys.argv[1] == "add":
        print(json.dumps(add(sys.argv[2], sys.argv[3], sys.argv[4] if len(sys.argv) > 4 else None), ensure_ascii=False))
    elif sys.argv[1] == "finish":
        finish()
    else:
        raise SystemExit("Nur add oder finish")
